import { customerReadyDestinations as destinations } from './destinations.js';

const TOETI_GLOBAL_MOBILITY_IMAGE = 'data:image/jpeg;base64,…15137 tokens truncated…';

export function globalHome(){return `<main class="th"><section class="hero" data-home-hero><div class="hero-sun" aria-hidden="true"></div><div class="copy" data-reveal><span class="eyebrow">TOETI GLOBAL · PEOPLE · PLACES · POSSIBILITIES</span><h1>TOETI<br><em>GLOBAL</em></h1><div class="hero-rule" aria-hidden="true"></div><p>Rental cars, tours and verified long-stay car rental — one clear way into every destination.</p><a class="primary" href="#destinations">FIND YOUR DESTINATION</a></div><div class="globe-wrap" data-globe><div id="globe" aria-label="Interactive world globe"></div><div class="globe-fallback" aria-label="Caribbean blue Earth"></div><div class="global-mobility-reference" aria-hidden="true" style="background-image:url(\'${TOETI_GLOBAL_MOBILITY_IMAGE}\')"></div></div></section><section class="streams" id="destinations" data-reveal-group><a class="stream car" href="/explore#cars"><span>CARS</span><i aria-hidden="true">▰</i><b>Freedom to explore</b></a><a class="stream experience" href="/explore#experiences"><span>TOURS &amp; EXPERIENCES</span><i aria-hidden="true">◇</i><b>See more. Feel more.</b></a><a class="stream longstay" href="/explore#longstay"><span>LONG-STAY CARS</span><i aria-hidden="true">✦</i><b>30–90 day rental for study & work</b></a></section><section class="live" id="live" data-scroll-reveal><div class="live-copy"><span class="eyebrow">LIVE NOW</span><h2>Start somewhere unforgettable.</h2><p>Only inventory ready for customers appears here.</p></div>${destinations.map(d=>`<a class="live-card" href="${d.url}"><div class="photo" style="background-image:linear-gradient(0deg,#041024ee 0,#0410241a 68%),url('${d.image}')"></div><div class="card-copy"><small>${d.label.toUpperCase()} · ${d.country.toUpperCase()}</small><h3>${d.destination}</h3><p>${d.copy}</p><strong>EXPLORE ${d.destination.toUpperCase()} →</strong></div></a>`).join('')}</section><section class="coming" id="experiences" data-scroll-reveal><span>TOURS &amp; EXPERIENCES</span><h2>See more. Feel more.</h2><p>New experiences will appear here as new destinations become available.</p></section><section class="coming" id="longstay" data-scroll-reveal><span>LONG-STAY CARS</span><h2>Stay longer. Keep moving.</h2><p>Verified 30, 60 and 90-day car rental for students, interns, temporary workers and expats will appear here when supplier rates and terms are confirmed.</p></section><section class="partner" data-scroll-reveal><span class="eyebrow">FOR LOCAL TRAVEL PARTNERS</span><h2>Bring your destination to the world.</h2><p>TOETI works with verified local car-rental and experience partners. Keep control of your inventory while we help international travellers discover it.</p><a class="primary" href="/partners">PARTNER WITH TOETI</a></section></main><script src="https://unpkg.com/gsap@3.13.0/dist/gsap.min.js"></script><script src="https://unpkg.com/lenis@1.3.17/dist/lenis.min.js"></script><script src="https://unpkg.com/three@0.160.0/build/three.min.js"></script><script src="https://unpkg.com/globe.gl@2.32.1/dist/globe.gl.min.js"></script><script>(()=>{const el=document.getElementById('globe'),fb=document.querySelector('.globe-fallback'),data=${JSON.stringify(destinations)};if(!el||!window.Globe)return fb.style.display='grid';try{const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;const g=Globe()(el).backgroundColor('rgba(0,0,0,0)').globeImageUrl('https://unpkg.com/three-globe/example/img/earth-blue-marble.jpg').bumpImageUrl('https://unpkg.com/three-globe/example/img/earth-topology.png').atmosphereColor('#5fd7ff').atmosphereAltitude(.18).pointsData(data.filter(d=>d.status==='SALES_GREEN')).pointLat('lat').pointLng('lng').pointColor(d=>d.category==='CAR'?'#f5a623':d.category==='EXPERIENCE'?'#48d58a':'#a979ff').pointAltitude(.06).pointRadius(.62).pointLabel(d=>(d.category==='CAR'?'Car rental':d.category==='EXPERIENCE'?'Tours & experiences':'Long-stay cars')+' · '+d.destination+' · '+d.country).onPointClick(d=>location.href=d.url);g.width(el.clientWidth).height(el.clientHeight);g.pointOfView({lat:-6.1659,lng:39.2026,altitude:2.1},1200);g.controls().autoRotate=!reduced;g.controls().autoRotateSpeed=.35;g.controls().enableZoom=true;new ResizeObserver(()=>{g.width(el.clientWidth).height(el.clientHeight)}).observe(el)}catch(e){fb.style.display='grid'}})();</script><script>(()=>{const reduced=matchMedia("(prefers-reduced-motion: reduce)").matches;if(!reduced&&window.Lenis){const lenis=new Lenis({duration:1.05,smoothWheel:true});const raf=t=>{lenis.raf(t);requestAnimationFrame(raf)};requestAnimationFrame(raf)}const animate=window.gsap?(el,values,opts)=>window.gsap.to(el,{...values,duration:opts.duration,ease:"power2.out"}):null;const reveal=el=>{if(!el||reduced)return;if(animate)animate(el,{opacity:[0,1],y:[24,0]},{duration:.65,easing:"ease-out"});else el.animate([{opacity:0,transform:"translateY(24px)"},{opacity:1,transform:"translateY(0)"}],{duration:650,fill:"both",easing:"cubic-bezier(.22,.8,.22,1)"})};const hero=document.querySelector("[data-reveal]");reveal(hero);document.querySelectorAll("[data-reveal-group] .stream").forEach((el,i)=>{if(reduced)return;el.style.opacity="0";setTimeout(()=>reveal(el),120+i*110)});const observer=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){reveal(entry.target);observer.unobserve(entry.target)}}),{threshold:.18});document.querySelectorAll("[data-scroll-reveal]").forEach(el=>observer.observe(el))})();</script>`}

